// Monthly ministry calendar. Records are saved only after explicit confirmation.
let ministryPerson='mine',ministryMonth='',ministryPin='',ministryReport=null,ministryRequest=0;
const MINISTRY_GEM='<svg viewBox="0 0 64 64" aria-hidden="true"><defs><linearGradient id="gem-fill" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#e8f7ee"/><stop offset=".5" stop-color="#a5cfca"/><stop offset="1" stop-color="#9286b9"/></linearGradient></defs><path d="M11 22 20 10h24l9 12-21 31Z" fill="url(#gem-fill)" stroke="#718f89" stroke-width="1.7" stroke-linejoin="round"/><path d="m11 22 42 0M20 10l6 12 6 31 6-31 6-12M26 22l6-12 6 12" fill="none" stroke="#fff" stroke-opacity=".65" stroke-width="1.3"/></svg>';
function ministryView(){if(!ministryMonth)ministryMonth=todayLocal().month;if(!ministryPin){ministryUnlock();return}ministryLoad()}
function ministryUnlock(){ministryReport=null;showProtectedUnlock('ministry',async (password,form)=>{let result;try{result=await ministryRead(ministryPerson,ministryMonth,password)}catch(err){throw Error(ministryError(err))}if(!form.isConnected||location.hash!=='#/ministry')return;ministryPin=password;routinePin=password;ministryReport=result;ministryRender()})}
function ministryError(err){return err.code==='PGRST202'?'봉사 보고 저장 공간을 먼저 설정해 주세요.':(err.message||'연결 상태를 확인해 주세요.')}
async function ministryRead(person,month,password=ministryPin){const r=await rpc('study_ministry_read',{p_password:password,p_person:person,p_month:month});if(!r?.ok)throw Error(r?.error||'불러오지 못했습니다.');return r}
async function ministryLoad(){const token=++ministryRequest,person=ministryPerson,month=ministryMonth;ministryReport=null;showCoupleLoading();try{let r=await ministryRead(person,month);if(token!==ministryRequest||location.hash!=='#/ministry')return;ministryReport=r;ministryRender()}catch(err){if(token!==ministryRequest||location.hash!=='#/ministry')return;$('#app').innerHTML=`<div class="notice" role="alert">${esc(ministryError(err))} <button class="link" id="ministry-retry">다시 시도</button></div><a class="back bottom-back" href="#/home">← 처음</a>`;$('#ministry-retry').onclick=ministryLoad}}
function ministryRender(){if(!ministryReport)return;const [y,m]=ministryMonth.split('-').map(Number),today=todayLocal(),start=new Date(y,m-1,1).getDay(),count=monthDays(ministryMonth),hours=ministryReport.hours||{},sum=Object.values(hours).reduce((n,v)=>n+(Number(v)||0),0);const days=Array(start).fill('<span class="ministry-empty" aria-hidden="true"></span>').concat(Array.from({length:count},(_,i)=>{let d=i+1,h=Number(hours[d]||0),isToday=today.month===ministryMonth&&today.day===d;return `<button type="button" class="ministry-day${isToday?' is-today':''}" data-ministry-day="${d}" aria-label="${y}년 ${m}월 ${d}일, ${h?h+'시간':'기록 없음'}"><span class="ministry-date">${d}</span><span class="ministry-hours">${h||''}</span></button>`}));$('#app').innerHTML=`<div class="workspace ministry"><div class="ministry-head"><h1 class="people-title">봉사 보고</h1><div class="filters ministry-people" aria-label="사용자 선택">${['mine','bora'].map(p=>`<button type="button" data-ministry-person="${p}" aria-pressed="${p===ministryPerson}" class="${p===ministryPerson?'active':''}">${personIdentity(p)}</button>`).join('')}</div></div><div class="routine-month ministry-month"><button type="button" class="month-arrow" id="ministry-prev" aria-label="이전 달">${UI_CHEVRON_LEFT}</button><label class="month-picker"><span aria-hidden="true">${y}년 ${m}월</span>${UI_CHEVRON_DOWN}<input type="month" id="ministry-month" value="${ministryMonth}" min="1900-01" max="9998-12" aria-label="연도와 월 선택"></label><button type="button" class="month-arrow" id="ministry-next" aria-label="다음 달">${UI_CHEVRON_RIGHT}</button></div>${today.month!==ministryMonth?'<button type="button" class="ministry-today" id="ministry-today">이번 달</button>':''}<div class="ministry-weekdays" aria-hidden="true">${['일','월','화','수','목','금','토'].map(d=>`<span>${d}</span>`).join('')}</div><div class="ministry-calendar" aria-label="${y}년 ${m}월 봉사 시간">${days.join('')}</div><div class="ministry-summary"><div><span>이번 달 봉사 시간</span><strong>${sum}시간</strong></div><button type="button" id="ministry-studies" aria-label="성서 연구 건수 수정"><span>성서 연구</span><span><strong>${ministryReport.studies===null?'—':ministryReport.studies+'건'}</strong>${UI_PENCIL}</span></button></div></div><a class="back bottom-back" href="#/home">← 처음</a>`;document.querySelectorAll('[data-ministry-person]').forEach(b=>b.onclick=()=>{if(ministryPerson===b.dataset.ministryPerson)return;ministryPerson=b.dataset.ministryPerson;ministryLoad()});$('#ministry-prev').onclick=()=>ministryChangeMonth(shiftMonth(ministryMonth,-1));$('#ministry-next').onclick=()=>ministryChangeMonth(shiftMonth(ministryMonth,1));$('#ministry-month').onchange=e=>ministryChangeMonth(e.target.value);$('#ministry-today')?.addEventListener('click',()=>ministryChangeMonth(todayLocal().month));document.querySelectorAll('[data-ministry-day]').forEach(b=>b.onclick=()=>ministryDayDialog(Number(b.dataset.ministryDay),b));$('#ministry-studies').onclick=e=>ministryStudiesDialog(e.currentTarget)}
function ministryChangeMonth(value){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(value)||Number(value.slice(0,4))<1900||Number(value.slice(0,4))>9998||value===ministryMonth)return;ministryMonth=value;ministryLoad()}
function ministryDialog(markup,trigger){const d=document.createElement('dialog');d.className='ministry-dialog';d.innerHTML=markup;d.setAttribute('aria-label',d.querySelector('h2')?.textContent||'봉사 보고');document.body.append(d);d.addEventListener('close',()=>{d.remove();if(trigger?.isConnected)trigger.focus()},{once:true});d.showModal();return d}
function ministryBurst(button,n){const layer=button.querySelector('.gem-effects');if(!layer||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const effect=document.createElement('span');effect.className='gem-pop';effect.innerHTML=MINISTRY_GEM+Array.from({length:n>=4?7:n>=2?4:2},(_,i)=>`<i style="--i:${i};--count:${n>=4?7:n>=2?4:2}"></i>`).join('');layer.append(effect);setTimeout(()=>effect.remove(),950)}
async function ministrySave(action,day,value,revision){const r=await rpc('study_ministry_write',{p_password:ministryPin,p_person:ministryPerson,p_month:ministryMonth,p_revision:revision,p_action:action,p_day:day,p_value:value});if(!r?.ok){let e=Error(r?.error||'저장하지 못했습니다.');e.conflict=!!r?.conflict;throw e}return r}
function ministryDayDialog(day,trigger){let draft=Number(ministryReport.hours?.[day]||0),revision=ministryReport.revision;const m=Number(ministryMonth.slice(5));const d=ministryDialog(`<div class="ministry-sheet"><div class="ministry-sheet-head"><h2>${m}월 ${day}일</h2><button type="button" class="tool-icon" data-close aria-label="닫기">${uiIcon('<path d="M18 6 6 18M6 6l12 12"/>')}</button></div><div class="ministry-draft"><strong id="ministry-draft-value" aria-live="polite">${draft}</strong><span>시간</span></div><button type="button" class="gem-button" aria-label="봉사 시간 1시간 추가">${MINISTRY_GEM}<span class="gem-effects" aria-hidden="true"></span></button><div class="ministry-sheet-actions"><button type="button" class="tool-icon ministry-undo" aria-label="마지막 1시간 되돌리기" title="1시간 되돌리기">${uiIcon('<path d="M3 7v6h6"/><path d="M3 13a9 9 0 1 1 2 6"/>')}</button><button type="button" class="primary ministry-save">저장</button></div><p class="ministry-sheet-error" role="status"></p><button type="button" class="link ministry-refresh" hidden>최신 기록 다시 불러오기</button></div>`,trigger);const val=d.querySelector('#ministry-draft-value'),undo=d.querySelector('.ministry-undo'),gem=d.querySelector('.gem-button'),save=d.querySelector('.ministry-save'),error=d.querySelector('.ministry-sheet-error');function refresh(){val.textContent=draft;undo.disabled=draft===0;gem.disabled=draft>=24}refresh();d.querySelector('[data-close]').onclick=()=>d.close();gem.onclick=()=>{if(draft>=24)return;draft++;refresh();ministryBurst(gem,draft)};undo.onclick=()=>{if(draft>0){draft--;refresh()}};d.querySelector('.ministry-refresh').onclick=()=>{d.close();ministryLoad()};save.onclick=async()=>{save.disabled=true;gem.disabled=true;undo.disabled=true;error.textContent='저장 중…';try{await ministrySave('hours',day,draft,revision);d.close();await ministryLoad()}catch(e){error.textContent=ministryError(e);if(e.conflict){save.disabled=true;d.querySelector('.ministry-refresh').hidden=false}else save.disabled=false;refresh()}}}
function ministryStudiesDialog(trigger){let revision=ministryReport.revision;const value=ministryReport.studies===null?'':ministryReport.studies;const d=ministryDialog(`<form class="ministry-sheet ministry-study-form"><div class="ministry-sheet-head"><h2>성서 연구</h2><button type="button" class="tool-icon" data-close aria-label="닫기">${uiIcon('<path d="M18 6 6 18M6 6l12 12"/>')}</button></div><label class="ministry-studies-label">이번 달 연구 건수<input id="ministry-study-count" type="number" inputmode="numeric" min="0" max="9999" step="1" value="${value}"></label><p class="ministry-sheet-error" role="status"></p><button type="button" class="link ministry-refresh" hidden>최신 기록 다시 불러오기</button><button class="primary ministry-study-save">저장</button></form>`,trigger);const input=d.querySelector('input'),save=d.querySelector('.ministry-study-save'),error=d.querySelector('.ministry-sheet-error');d.querySelector('[data-close]').onclick=()=>d.close();d.querySelector('.ministry-refresh').onclick=()=>{d.close();ministryLoad()};d.querySelector('form').onsubmit=async e=>{e.preventDefault();if(!input.checkValidity()){input.reportValidity();return}const value=input.value===''?null:Number(input.value);save.disabled=true;error.textContent='저장 중…';try{await ministrySave('studies',null,value,revision);d.close();await ministryLoad()}catch(err){error.textContent=ministryError(err);if(err.conflict)d.querySelector('.ministry-refresh').hidden=false;else save.disabled=false}}}
